// hdf-convert: argument access, UTF-8 paths, error reports, the --out guard, the oracle-test registry.
#include "cli.hpp"

#include "hdf_cli_config.hpp"  // generated by CMake: kProjectRoot

#include "../src/base/base_util.hpp"  // utf8_lossy

#include <cstdio>
#include <cstdlib>
#include <cwctype>
#include <system_error>

namespace hdf::cli {

std::optional<std::string> Args::get(std::string_view name) const {
    for (const auto& [k, v] : options)
        if (k == name) return v;
    return std::nullopt;
}

std::optional<std::filesystem::path> Args::path(std::string_view name) const {
    auto v = get(name);
    if (!v) return std::nullopt;
    return u8path(*v);
}

bool Args::has(std::string_view flag) const {
    for (const std::string& f : flags)
        if (f == flag) return true;
    return false;
}

std::filesystem::path u8path(std::string_view utf8) {
    return std::filesystem::path(std::u8string(utf8.begin(), utf8.end()));
}

// Never throws on a name with an unpaired UTF-16 surrogate (fix-wave1 L1): those characters become U+FFFD.
std::string to_utf8(const std::filesystem::path& p) { return base::utf8_lossy(p, true); }

int report(std::string_view command, const Error& e) {
    std::fprintf(stderr, "hdf-convert %.*s: %s%s%s\n", int(command.size()), command.data(), e.code.c_str(),
                 e.detail.empty() ? "" : ": ", e.detail.c_str());
    return e.code == "todo" ? kExitTodo : kExitFail;
}

namespace {

std::filesystem::path normalized(const std::filesystem::path& p) {
    std::error_code ec;
    std::filesystem::path abs = std::filesystem::absolute(p, ec);
    if (ec) abs = p;
    std::filesystem::path canon = std::filesystem::weakly_canonical(abs, ec);
    return (ec ? abs : canon).lexically_normal();
}

// Windows paths compare without case.
bool same_component(const std::filesystem::path& a, const std::filesystem::path& b) {
    const std::wstring x = a.wstring(), y = b.wstring();
    if (x.size() != y.size()) return false;
    for (std::size_t i = 0; i < x.size(); ++i)
        if (std::towlower(x[i]) != std::towlower(y[i])) return false;
    return true;
}

// child is parent or inside it
bool within(const std::filesystem::path& child, const std::filesystem::path& parent) {
    auto c = child.begin(), p = parent.begin();
    for (; p != parent.end(); ++p, ++c) {
        if (p->empty()) continue;  // trailing separator
        if (c == child.end() || !same_component(*c, *p)) return false;
    }
    return true;
}

std::optional<std::filesystem::path> env_path(const wchar_t* name) {
#ifdef _WIN32
    wchar_t* v = nullptr;
    std::size_t n = 0;
    if (_wdupenv_s(&v, &n, name) != 0 || v == nullptr) return std::nullopt;
    std::filesystem::path p(v);
    std::free(v);
    return p;
#else
    (void)name;
    return std::nullopt;
#endif
}

}  // namespace

Result<void> check_out_dir(const std::filesystem::path& out, const std::vector<std::filesystem::path>& inputs) {
    const std::filesystem::path o = normalized(out);
    const std::filesystem::path root = normalized(u8path(kProjectRoot));
    if (within(o, root)) {
        const std::filesystem::path rel = o.lexically_relative(root);
        const std::string first = rel.empty() ? std::string() : to_utf8(*rel.begin());
        if (first.rfind("build-", 0) != 0 || first.size() <= 6)
            return fail("out.refused", to_utf8(o) + " is inside the project: the outputs are made from your games, "
                                                    "use a build-*/ folder or a scratch folder");
        if (first == "build-hdf")
            return fail("out.refused", "build-hdf holds the current mod build: use another build-*/ folder");
    }
    for (const std::filesystem::path& in : inputs) {
        const std::filesystem::path i = normalized(in);
        if (within(o, i) || within(i, o))
            return fail("out.refused", to_utf8(o) + " overlaps the input " + to_utf8(i));
    }
    // The real Dusklight install data (never write there from the CLI).
    if (auto appdata = env_path(L"APPDATA")) {
        const std::filesystem::path tr = normalized(*appdata / "TwilitRealm");
        if (within(o, tr)) return fail("out.refused", "refusing to write into %APPDATA%\\TwilitRealm");
    }
    return {};
}

std::vector<OracleTest>& oracle_tests() {
    static std::vector<OracleTest> tests;
    return tests;
}

OracleReg::OracleReg(std::string_view module, std::string_view what, OracleFn fn) {
    oracle_tests().push_back(OracleTest{module, what, fn});
}

}  // namespace hdf::cli
